patches.value:
query auditLog($id: String!, $workspaceId: String!) {
  auditLog(id: $id, workspaceId: $workspaceId) {
    context
    createdAt
    environmentId
    eventType
    id
    payload
    projectId
    workspaceId
  }
}

query auditLogs($after: String, $before: String, $filter: AuditLogFilterInput, $first: Int, $last: Int, $sort: SortOrder, $workspaceId: String!) {
  auditLogs(after: $after, before: $before, filter: $filter, first: $first, last: $last, sort: $sort, workspaceId: $workspaceId) {
    edges {
      cursor
      node {
        context
        createdAt
        environmentId
        eventType
        id
        payload
        projectId
        workspaceId
      }
    }
    pageInfo {
      endCursor
      hasNextPage
      hasPreviousPage
      startCursor
    }
  }
}
